// Contract ABIs and deployed addresses. Both files are GENERATED by `pnpm sync`
// (scripts/sync-abis.js) from the Foundry build output and the deployment files.
// All contract access from the app goes through this module.
import abis from "@/contracts/abis.json";
import addresses from "@/contracts/addresses.json";

export { abis };

/** All synced addresses for a chain id, or null when nothing is deployed there. */
export function addressesFor(chainId) {
  return addresses[String(chainId)] ?? null;
}

/** One contract address on a chain (for example addressOf(31337, "ReportRegistry")). */
export function addressOf(chainId, name) {
  return addressesFor(chainId)?.[name];
}

export const SEVERITIES = ["Low", "Medium", "High", "Critical"];
